import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { parseEnv } from 'node:util';

/**
 * The one environment policy for every local command (Makefile, npm scripts, Vitest e2e setup).
 * Precedence, highest first: a variable already exported in the environment, then `.env.local`
 * (the user's own settings, git-ignored, never written by tooling), then `.env.deploy` (generated by
 * `make up`: table name and API URL, git-ignored), then `.env.example` (non-secret dev defaults).
 *
 * Pure functions; `scripts/load-env.ts` applies them (preload, shell export, Vitest setup).
 */
export const ENV_FILES = ['.env.local', '.env.deploy', '.env.example'] as const;

const ROOT = fileURLToPath(new URL('..', import.meta.url));

/** Applies the policy to `env` and returns the names the files define (resolved values are in `env`). */
export function loadEnv(env: NodeJS.ProcessEnv = process.env, root: string = ROOT): string[] {
  const names = new Set<string>();
  for (const file of ENV_FILES) {
    const path = `${root}/${file}`;
    if (!existsSync(path)) continue;
    for (const [name, value] of Object.entries(parseEnv(readFileSync(path, 'utf8')))) {
      names.add(name);
      // Earlier sources (exported env, then the files in order) win: only fill what is still unset.
      if (env[name] === undefined && value !== undefined) env[name] = value;
    }
  }
  return [...names];
}

/** POSIX shell `export` lines for the resolved values, single-quoted so `$default` stays literal. */
export function toShellExports(names: readonly string[], env: NodeJS.ProcessEnv = process.env): string {
  const quote = (v: string) => `'${v.replaceAll("'", `'\\''`)}'`;
  return names
    .filter((n) => env[n] !== undefined)
    .map((n) => `export ${n}=${quote(env[n] as string)}`)
    .join('\n');
}
